parameters.jsCode:
// Regenerate the test-case comment only when one of these Jira fields changes.
const WATCHED_FIELDS = ['description', 'summary'];

// The Jira trigger emits the raw Atlassian payload at $json; some builds nest it under `body`.
const entry = $input.first().json || {};
const payload = entry.body && entry.body.issue ? entry.body : entry;

const issue = payload.issue || {};
const fields = issue.fields || {};
const changedFields = ((payload.changelog && payload.changelog.items) || []).map((i) => i.field);
const webhookEvent = payload.webhookEvent || '';

// Loop guard: act on creation, or only when the requirement text itself changed.
// Our own comment is never in WATCHED_FIELDS, so it cannot re-trigger the flow.
const requirementChanged = changedFields.some((f) => WATCHED_FIELDS.includes(f));
const shouldGenerate = webhookEvent === 'jira:issue_created' || requirementChanged;

// Jira Cloud sends descriptions as Atlassian Document Format; Jira Server sends plain text.
function adfToText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).join('');

  switch (node.type) {
    case 'text':
      return node.text || '';
    case 'hardBreak':
      return '\n';
    case 'paragraph':
    case 'heading':
    case 'codeBlock':
      return (node.content ? node.content.map(adfToText).join('') : '') + '\n';
    case 'listItem':
      return '- ' + (node.content ? node.content.map(adfToText).join('').trim() : '') + '\n';
    case 'tableRow':
      return (node.content ? node.content.map(adfToText).join(' | ').trim() : '') + '\n';
    default:
      return node.content ? node.content.map(adfToText).join('') : '';
  }
}

const rawDescription = fields.description;
let requirementText = '';
if (rawDescription && typeof rawDescription === 'object') {
  requirementText = adfToText(rawDescription).replace(/\n{3,}/g, '\n\n').trim();
} else if (typeof rawDescription === 'string') {
  requirementText = rawDescription.trim();
}

const summary = fields.summary || '';

return [{
  json: {
    should_generate: shouldGenerate && (requirementText.length > 0 || summary.length > 0),
    ticket_key: issue.key || '',
    summary: summary,
    requirement_text: requirementText,
    issue_type: (fields.issuetype && fields.issuetype.name) || ''
  }
}];

parameters.text:
=Generate BDD/Gherkin test cases for this Jira requirement.

Jira key: {{ $json.ticket_key || 'n/a' }}
Issue type: {{ $json.issue_type || 'n/a' }}
Summary: {{ $json.summary || 'n/a' }}

Requirement description:
{{ $json.requirement_text || 'not provided' }}

Cover positive (happy path), negative (invalid / error handling) and edge (boundary / unusual) scenarios.

