{
  "type": "object",
  "properties": {
    "feature_name": {
      "type": "string",
      "description": "Name of the feature under test"
    },
    "feature_description": {
      "type": "string",
      "description": "One or two sentences describing the feature"
    },
    "assumptions": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Ambiguities or preconditions assumed from the requirement"
    },
    "test_cases": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": { "type": "string" },
          "title": { "type": "string" },
          "category": {
            "type": "string",
            "enum": ["positive", "negative", "edge"]
          },
          "priority": {
            "type": "string",
            "enum": ["High", "Medium", "Low"]
          },
          "tags": {
            "type": "array",
            "items": { "type": "string" }
          },
          "given": {
            "type": "array",
            "items": { "type": "string" }
          },
          "when": {
            "type": "array",
            "items": { "type": "string" }
          },
          "then": {
            "type": "array",
            "items": { "type": "string" }
          }
        },
        "required": ["title", "category", "given", "when", "then"]
      }
    }
  },
  "required": ["feature_name", "test_cases"]
}

