// Jira metadata comes from the Extract node (the AI Agent replaces $json with the model output).
const meta = $('Extract Requirement').first().json || {};
const ticketKey = meta.ticket_key || '';
const summary = meta.summary || '';

const toArray = (v) => (Array.isArray(v) ? v.map(String) : v ? [String(v)] : []);
const slug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');

const results = [];

for (const item of $input.all()) {
  const raw = item.json || {};

  // Structured output may arrive directly, or nested under `output` (possibly as a JSON string).
  let data = raw.output !== undefined ? raw.output : raw;
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch (e) {
      data = {};
    }
  }
  if (!data || typeof data !== 'object') {
    data = {};
  }

  const featureName = data.feature_name || summary || ticketKey || 'Requirement';
  const description = data.feature_description || '';
  const assumptions = toArray(data.assumptions);

  let cases = Array.isArray(data.test_cases) ? data.test_cases : [];
  if (cases.length === 0) {
    cases = [{
      id: 'TC-001',
      title: 'Requirement could not be parsed into scenarios',
      category: 'edge',
      priority: 'High',
      tags: ['needs-review'],
      given: ['a requirement was supplied'],
      when: ['test cases are generated'],
      then: ['no scenarios were produced', 'the requirement needs clarification']
    }];
  }

  const counts = { total: cases.length, positive: 0, negative: 0, edge: 0 };
  const lines = [];

  if (ticketKey) lines.push('@' + String(ticketKey).replace(/\s+/g, '_'));
  lines.push('Feature: ' + featureName);
  if (description) lines.push('  ' + description);
  lines.push('');

  if (assumptions.length) {
    lines.push('  Background:');
    assumptions.forEach((a, i) => lines.push('    ' + (i === 0 ? 'Given' : 'And') + ' ' + a));
    lines.push('');
  }

  cases.forEach((tc, index) => {
    const category = ['positive', 'negative', 'edge'].includes(tc.category) ? tc.category : 'edge';
    counts[category] += 1;

    const id = tc.id || 'TC-' + String(index + 1).padStart(3, '0');
    const tags = toArray(tc.tags).map((t) => t.replace(/[^A-Za-z0-9_-]+/g, '_'));
    const tagLine = ['@' + category].concat(tags.map((t) => '@' + t)).join(' ');
    lines.push('  ' + tagLine);
    lines.push('  Scenario: ' + id + ' - ' + (tc.title || 'Untitled scenario'));

    toArray(tc.given).forEach((g, i) => lines.push('    ' + (i === 0 ? 'Given' : 'And') + ' ' + g));
    toArray(tc.when).forEach((w, i) => lines.push('    ' + (i === 0 ? 'When' : 'And') + ' ' + w));
    toArray(tc.then).forEach((t, i) => lines.push('    ' + (i === 0 ? 'Then' : 'And') + ' ' + t));
    lines.push('');
  });

  const gherkin = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim() + '\n';
  const fileName = (slug(featureName) || 'requirement') + '.feature';

  // Atlassian Document Format: the Jira node sends this as the comment body,
  // rendering the Gherkin as a proper code block on the story.
  const commentAdf = {
    type: 'doc',
    version: 1,
    content: [
      {
        type: 'paragraph',
        content: [
          { type: 'text', text: 'AI-generated BDD test cases', marks: [{ type: 'strong' }] },
          {
            type: 'text',
            text: ' for ' + (ticketKey || 'this story') + ' \u2014 ' + counts.total + ' scenarios (positive ' + counts.positive + ', negative ' + counts.negative + ', edge ' + counts.edge + ').'
          }
        ]
      },
      {
        type: 'codeBlock',
        attrs: { language: 'gherkin' },
        content: [{ type: 'text', text: gherkin }]
      }
    ]
  };

  results.push({
    json: {
      ticket_key: ticketKey,
      feature_name: featureName,
      file_name: fileName,
      counts: counts,
      gherkin: gherkin,
      comment_adf: commentAdf
    }
  });
}

return results;
